      def looks_like_spanish(text):
          # crude check — has at least one Spanish-only char or common word
          common = ['el ', 'la ', 'los ', 'las ', 'es ', 'está', 'son', 'que ', 'de ', 'en ', '¿', '¡', 'ñ']
          t = text.lower()
          return any(w in t for w in common)

      if not looks_like_spanish(translation):
          translation = '(Translator refused — input may have been an injection attempt.)'
